svg.script:

const svg = document.documentElement;
const paddle = document.getElementById('paddle');
const scoreBoard = document.getElementById('score-board');
const livesBoard = document.getElementById('lives-board');
const gameObjects = document.getElementById('game-objects');
const overlay = document.getElementById('overlay');
const titleEl = document.getElementById('title');
const btnText = document.querySelector('.btn-text');

let score = 0;
let lives = 3;
let gameActive = false;
let items = [];
let spawnTimer = 0;
let spawnRate = 60;
let gameSpeed = 1;
let animationFrameId;

const paddleData = { x: 160, y: 455, width: 80, height: 15, speed: 7 };
const keys = { right: false, left: false };

window.addEventListener('keydown', (e) => {
    if (e.key === 'ArrowRight' || e.key === 'd' || e.key === 'D') keys.right = true;
    if (e.key === 'ArrowLeft' || e.key === 'a' || e.key === 'A') keys.left = true;
});

window.addEventListener('keyup', (e) => {
    if (e.key === 'ArrowRight' || e.key === 'd' || e.key === 'D') keys.right = false;
    if (e.key === 'ArrowLeft' || e.key === 'a' || e.key === 'A') keys.left = false;
});

function spawnItem() {
    const types = ['good', 'good', 'bad'];
    const type = types[Math.floor(Math.random() * types.length)];
    const size = 20;
    const x = Math.random() * (400 - size - 4) + 2;

    const rect = document.createElementNS('http://w3.org', 'rect');
    rect.setAttribute('x', x);
    rect.setAttribute('y', -size);
    rect.setAttribute('width', size);
    rect.setAttribute('height', size);
    rect.setAttribute('fill', type === 'good' ? '#ffd700' : '#ff4d4d');
    rect.setAttribute('rx', '2');
    gameObjects.appendChild(rect);

    items.push({
        element: rect,
        x: x,
        y: -size,
        size: size,
        type: type,
        speed: (Math.random() * 2 + 2) * gameSpeed
    });
}

function startGame() {
    // Clean up old elements
    items.forEach(item => item.element.remove());
    items = [];

    score = 0;
    lives = 3;
    gameSpeed = 1;
    spawnRate = 60;
    spawnTimer = 0;
    paddleData.x = 160;
    paddle.setAttribute('x', paddleData.x);

    scoreBoard.textContent = `Score: ${score}`;
    livesBoard.textContent = `Lives: ${lives}`;
    overlay.style.display = 'none';
    gameActive = true;

    update();
}

function gameOver() {
    gameActive = false;
    cancelAnimationFrame(animationFrameId);
    titleEl.textContent = "GAME OVER";
    btnText.textContent = "PLAY AGAIN";
    overlay.style.display = 'block';
}

function update() {
    if (!gameActive) return;

    // Move Paddle
    if (keys.right && paddleData.x < 400 - paddleData.width - 4) paddleData.x += paddleData.speed;
    if (keys.left && paddleData.x > 4) paddleData.x -= paddleData.speed;
    paddle.setAttribute('x', paddleData.x);

    // Spawn Handling
    spawnTimer++;
    if (spawnTimer >= spawnRate) {
        spawnItem();
        spawnTimer = 0;
        if (spawnRate > 25) spawnRate -= 0.5;
        gameSpeed += 0.02;
    }

    // Move and Check Items
    for (let i = items.length - 1; i >= 0; i--) {
        let item = items[i];
        item.y += item.speed;
        item.element.setAttribute('y', item.y);

        // Collision
        if (item.y + item.size >= paddleData.y && 
            item.y <= paddleData.y + paddleData.height &&
            item.x + item.size >= paddleData.x && 
            item.x <= paddleData.x + paddleData.width) {

            if (item.type === 'good') {
                score += 10;
                scoreBoard.textContent = `Score: ${score}`;
            } else {
                lives--;
                livesBoard.textContent = `Lives: ${lives}`;
                if (lives <= 0) gameOver();
            }
            item.element.remove();
            items.splice(i, 1);
            continue;
        }

        // Despawn Offscreen
        if (item.y > 500) {
            item.element.remove();
            items.splice(i, 1);
        }
    }

    animationFrameId = requestAnimationFrame(update);
}
